mapper.insert:
INSERT INTO sincronizacion_ejecucion (
    empresa_id, sucursal_id, puntoventa_id, funcion, estado,
    transaccion, mensajes, fecha_hora_siat, error
) VALUES (
    #{empresaId}, #{sucursalId}, #{puntoventaId}, #{funcion}, #{estado},
    #{transaccion}, CAST(#{mensajes} AS jsonb), #{fechaHoraSiat}, #{error}
)

INSERT INTO sincronizacion_actividad (
    ejecucion_id, codigo_caeb, descripcion, tipo_actividad
) VALUES (
    #{ejecucionId}, #{codigoCaeb}, #{descripcion}, #{tipoActividad}
)

INSERT INTO sincronizacion_leyenda_factura (
    ejecucion_id, codigo_actividad, descripcion_leyenda
) VALUES (
    #{ejecucionId}, #{codigoActividad}, #{descripcionLeyenda}
)

INSERT INTO sincronizacion_actividad_documento_sector (
    ejecucion_id, codigo_actividad, codigo_documento_sector, tipo_documento_sector
) VALUES (
    #{ejecucionId}, #{codigoActividad}, #{codigoDocumentoSector}, #{tipoDocumentoSector}
)

INSERT INTO sincronizacion_producto_servicio (
    ejecucion_id, codigo_actividad, codigo_producto, descripcion_producto
) VALUES (
    #{ejecucionId}, #{codigoActividad}, #{codigoProducto}, #{descripcionProducto}
)

choose.when:
SELECT codigo::text AS codigo,
       descripcion,
       CAST(NULL AS text) AS detalle,
       CAST(NULL AS text) AS nandina
FROM sincronizacion_motivo_anulacion
WHERE ejecucion_id = #{ejecucionId}
UNION ALL
